foreach($big in @($false,$true)){foreach($replacement in $replacements){
 $owner=[Text.Encoding]([Text.UnicodeEncoding]::new($big,$true,$false)).Clone();$text=[string]::new([char[]][int[]]$replacement);$owner.EncoderFallback=[Text.EncoderReplacementFallback]::new($text);$owner.DecoderFallback=[Text.DecoderReplacementFallback]::new($text);[int[]]$high=if($big){@(216,0)}else{@(0,216)};[int[]]$low=if($big){@(220,0)}else{@(0,220)};[int[]]$normal=if($big){@(0,65)}else{@(65,0)};$rows=[Collections.Generic.List[object]]::new()
 foreach($encode in @($false)){$inputs=if($encode){,@(@(),@(65),@(55296),@(56320),@(55296,65),@(55296,56320),@(65,55296),@(56320,55296))}else{,@(@(),@(65),@($normal),@($high),@($low),@($high+$low),@($high+$normal),@($low+@(255)))};$seeds=if($encode){,@(@(),@(55296))}else{,@(@(),@(65),@($high),@($high+@(0)))}
 foreach($stateful in @($false,$true)){$seedIds=if($stateful){0..($seeds.Count-1)}else{@(0)};$flushModes=if($stateful){@($false,$true)}else{@($true)};foreach($seedId in $seedIds){foreach($sourceId in 0..($inputs.Count-1)){foreach($flush in $flushModes){foreach($countBefore in @($false,$true)){foreach($capacity in @(0,1,2,4,8)){foreach($offset in @(0,2)){
  $codec=if($encode){$owner.GetEncoder()}else{$owner.GetDecoder()};$units=[int[]]$inputs[$sourceId];$seed=[int[]]$seeds[$seedId];$source=if($encode){,[char[]]$units}else{,[byte[]]$units};$seedInput=if($encode){,[char[]]$seed}else{,[byte[]]$seed};$empty=if($encode){,[char[]]@()}else{,[byte[]]@()};$seedDest=if($encode){,[byte[]](@(99)*16)}else{,[char[]](@(99)*16)};$seedResult=$null;if($stateful){$seedResult=Data-Call $owner $codec $encode $true $false $seedInput $seedDest 0 $false}
  $countResult=$null;if($countBefore){$countResult=Data-Call $owner $codec $encode $stateful $true $source $null 0 $flush};$dest=if($encode){,[byte[]](@(99)*($capacity+$offset))}else{,[char[]](@(99)*($capacity+$offset))};$write=Data-Call $owner $codec $encode $stateful $false $source $dest $offset $flush;$tail=if($encode){,[byte[]](@(99)*16)}else{,[char[]](@(99)*16)};$tailResult=Data-Call $owner $codec $encode $stateful $false $empty $tail 0 $true;$buffer=@();if($stateful){foreach($probe in @('remaining','next','remaining','previous')){try{$v=switch($probe){'remaining'{$codec.FallbackBuffer.Remaining};'next'{[int]$codec.FallbackBuffer.GetNextChar()};'previous'{[int]$codec.FallbackBuffer.MovePrevious()}};$r=[ordered]@{ok=$true;count=$v}}catch{$r=Failure-Of $_};$r.remaining=$codec.FallbackBuffer.Remaining;$buffer+=@([ordered]@{operation=$probe;result=$r})}}
  $rows.Add([ordered]@{encode=$encode;stateful=$stateful;seed=$seed;source=$units;flush=$flush;countBefore=$countBefore;capacity=$capacity;offset=$offset;seedResult=$seedResult;seedAfter=[int[]]$seedDest;countResult=$countResult;writeResult=$write;after=[int[]]$dest;tailResult=$tailResult;tailAfter=[int[]]$tail;buffer=$buffer})
 }}}}}}}
 };$profiles.Add([ordered]@{bigEndian=$big;replacement=[int[]]$replacement;rows=$rows.ToArray()})
